1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <meta name="theme-color" content="#0d0d17">
9	  <title>Pulsing Circle</title>
10	  <style>
11	    :root {
12	      --circle-hue: #8ec5ff;
13	      --circle-core: #4a7dd9;
14	      --circle-shadow: #1f3a75;
15	      --cycle: 2.5s;
16	    }
17	    * {
18	      margin: 0;
19	      padding: 0;
20	      box-sizing: border-box;
21	    }
22	    body {
23	      width: 100vw;
24	      height: 100vh;
25	      height: 100dvh;
26	      display: flex;
27	      flex-direction: column;
28	      justify-content: center;
29	      align-items: center;
30	      gap: 24px;
31	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
32	      overflow: hidden;
33	    }
34	    svg {
35	      width: min(400px, 80vmin);
36	      height: min(400px, 80vmin);
37	      overflow: visible;
38	      cursor: pointer;
39	      user-select: none;
40	      -webkit-tap-highlight-color: transparent;
41	      transition: filter 0.3s ease;
42	    }
43	    .circle-btn:hover svg {
44	      filter: brightness(1.08);
45	    }
46	    .ambient {
47	      fill: var(--circle-hue);
48	      opacity: 0.12;
49	      filter: blur(30px);
50	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
51	      transform-origin: 200px 200px;
52	      will-change: transform, opacity;
53	    }
54	    .core {
55	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
56	      transform-origin: 200px 200px;
57	      filter: url(#glow);
58	      will-change: transform, opacity;
59	    }
60	    .highlight {
61	      fill: url(#highlightGradient);
62	      transform-origin: 200px 200px;
63	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
64	      pointer-events: none;
65	      will-change: transform, opacity;
66	    }
67	    .ring {
68	      fill: none;
69	      stroke: var(--circle-hue);
70	      stroke-width: 2.5;
71	      transform-origin: 200px 200px;
72	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
73	      will-change: transform, opacity, stroke-width;
74	    }
75	    .ring--delay-1 {
76	      animation-delay: calc(var(--cycle) / 3);
77	    }
78	    .ring--delay-2 {
79	      animation-delay: calc(var(--cycle) / 3 * 2);
80	    }
81	    @keyframes pulse {
82	      0%, 100% {
83	        transform: scale(1);
84	        opacity: 0.9;
85	      }
86	      50% {
87	        transform: scale(1.05);
88	        opacity: 1;
89	      }
90	    }
91	    @keyframes breathe {
92	      0%, 100% {
93	        transform: scale(0.95);
94	        opacity: 0.1;
95	      }
96	      50% {
97	        transform: scale(1.1);
98	        opacity: 0.18;
99	      }
100	    }
101	    @keyframes ripple {
102	      0% {
103	        transform: scale(1);
104	        opacity: 0.6;
105	        stroke-width: 2.5;
106	      }
107	      100% {
108	        transform: scale(1.35);
109	        opacity: 0;
110	        stroke-width: 0.5;
111	      }
112	    }
113	    body.paused .core,
114	    body.paused .ring,
115	    body.paused .ambient,
116	    body.paused .highlight {
117	      animation-play-state: paused;
118	    }
119	    /* Force-paused until JS takes over (below), avoiding a flash of motion;
120	       once JS is ready, control defers entirely to body.paused so the user
121	       can still explicitly resume even with reduced motion preferred. */
122	    @media (prefers-reduced-motion: reduce) {
123	      body:not(.js-ready) .core,
124	      body:not(.js-ready) .ring,
125	      body:not(.js-ready) .ambient,
126	      body:not(.js-ready) .highlight {
127	        animation-play-state: paused;
128	      }
129	    }
130	    .speed-label {
131	      color: var(--circle-hue);
132	      font-family: system-ui, sans-serif;
133	      font-size: 0.85rem;
134	      letter-spacing: 0.05em;
135	      opacity: 0.85;
136	      user-select: none;
137	      text-align: center;
138	    }
139	    .hint {
140	      display: block;
141	      margin-top: 4px;
142	      font-size: 0.7rem;
143	      opacity: 1;
144	    }
145	    .controls {
146	      display: flex;
147	      align-items: center;
148	      gap: 12px;
149	      max-width: min(320px, 90vw);
150	    }
151	    .pause-btn {
152	      display: inline-flex;
153	      align-items: center;
154	      justify-content: center;
155	      width: 36px;
156	      height: 36px;
157	      padding: 0;
158	      border-radius: 50%;
159	      border: 1px solid var(--circle-hue);
160	      background: transparent;
161	      color: var(--circle-hue);
162	      cursor: pointer;
163	      touch-action: manipulation;
164	      transition: background 0.2s ease;
165	    }
166	    .pause-btn:hover {
167	      background: rgba(142, 197, 255, 0.15);
168	    }
169	    .pause-btn:focus-visible {
170	      outline: 2px solid var(--circle-hue);
171	      outline-offset: 2px;
172	    }
173	    @media (prefers-contrast: more) {
174	      .pause-btn {
175	        border-width: 2px;
176	      }
177	      .ring {
178	        stroke-width: 3.5;
179	      }
180	    }
181	    .pause-btn svg {
182	      width: 14px;
183	      height: 14px;
184	    }
185	    .circle-btn {
186	      display: inline-flex;
187	      padding: 0;
188	      border: none;
189	      background: none;
190	      cursor: pointer;
191	      touch-action: manipulation;
192	      -webkit-tap-highlight-color: transparent;
193	      border-radius: 50%;
194	    }
195	    .circle-btn:focus-visible svg {
196	      outline: 2px solid var(--circle-hue);
197	      outline-offset: 8px;
198	      border-radius: 50%;
199	    }
200	  </style>
201	</head>
202	<body>
203	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation. Click to change pulse speed." aria-describedby="speedText" title="Click to change pulse speed">
204	  <svg viewBox="0 0 400 400" focusable="false" aria-hidden="true">
205	    <defs>
206	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
207	        <stop offset="0%" style="stop-color: var(--circle-hue)"/>
208	        <stop offset="55%" style="stop-color: var(--circle-core)"/>
209	        <stop offset="100%" style="stop-color: var(--circle-shadow)"/>
210	      </radialGradient>
211	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
212	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
213	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
214	      </radialGradient>
215	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
216	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
217	        <feColorMatrix in="blur" type="matrix"
218	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
219	        <feMerge>
220	          <feMergeNode in="tintedBlur"/>
221	          <feMergeNode in="SourceGraphic"/>
222	        </feMerge>
223	      </filter>
224	    </defs>
225	    <circle class="ambient" cx="200" cy="200" r="160"/>
226	    <circle class="ring" cx="200" cy="200" r="140"/>
227	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
228	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
229	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
230	    <circle class="highlight" cx="200" cy="200" r="140"/>
231	  </svg>
232	  </button>
233	  <div class="controls">
234	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation" title="Pause animation">
235	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
236	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
237	      </svg>
238	    </button>
239	    <p class="speed-label" id="speedLabel">
240	      <span id="speedText" aria-live="polite">Normal speed</span>
241	      <span class="hint" aria-hidden="true">Click circle to change speed</span>
242	    </p>
243	  </div>
244	  <script>
245	    const circleBtn = document.getElementById('circleBtn');
246	    const speedText = document.getElementById('speedText');
247	    const pauseBtn = document.getElementById('pauseBtn');
248	    const pauseIcon = document.getElementById('pauseIcon');
249	    const animatedEls = document.querySelectorAll('.core, .ring, .ambient, .highlight');
250	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
251	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
252	    const speeds = [
253	      { value: '2.5s', name: 'Normal speed' },
254	      { value: '1.2s', name: 'Fast speed' },
255	      { value: '4.5s', name: 'Slow speed' },
256	    ];
257	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
258	    let speedIndex = 0;
259	    let manuallyPaused = reducedMotionQuery.matches;
260	    // Once the user has explicitly toggled pause/play, respect that choice
261	    // instead of letting a later OS-level reduced-motion change override it.
262	    let userHasChosen = false;
263	
264	    const STORAGE_KEY = 'pulsing-circle-prefs';
265	    try {
266	      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
267	      if (saved && Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex]) {
268	        speedIndex = saved.speedIndex;
269	        circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
270	      }
271	      if (saved && typeof saved.manuallyPaused === 'boolean') {
272	        manuallyPaused = saved.manuallyPaused;
273	        userHasChosen = true;
274	      }
275	    } catch {
276	      // Ignore malformed or inaccessible storage; fall back to defaults.
277	    }
278	
279	    function savePrefs() {
280	      try {
281	        localStorage.setItem(STORAGE_KEY, JSON.stringify({ speedIndex, manuallyPaused }));
282	      } catch {
283	        // Storage may be unavailable (e.g. private browsing); ignore.
284	      }
285	    }
286	
287	    function updateLabels() {
288	      const { name } = speeds[speedIndex];
289	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
290	    }
291	
292	    function cycleSpeed() {
293	      speedIndex = (speedIndex + 1) % speeds.length;
294	      const { value } = speeds[speedIndex];
295	      circleBtn.style.setProperty('--cycle', value);
296	      // Restart animations from the beginning so the new speed feels immediate
297	      // instead of jumping mid-cycle.
298	      animatedEls.forEach((el) => {
299	        el.style.animation = 'none';
300	        void el.offsetWidth;
301	        el.style.animation = '';
302	      });
303	      updateLabels();
304	      savePrefs();
305	    }
306	
307	    function applyPauseState() {
308	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
309	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
310	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
311	      pauseBtn.setAttribute('title', manuallyPaused ? 'Resume animation' : 'Pause animation');
312	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
313	      updateLabels();
314	    }
315	
316	    function togglePause() {
317	      manuallyPaused = !manuallyPaused;
318	      userHasChosen = true;
319	      applyPauseState();
320	      savePrefs();
321	    }
322	
323	    circleBtn.addEventListener('click', cycleSpeed);
324	    pauseBtn.addEventListener('click', togglePause);
325	
326	    document.addEventListener('visibilitychange', applyPauseState);
327	
328	    reducedMotionQuery.addEventListener('change', (e) => {
329	      if (userHasChosen) return;
330	      manuallyPaused = e.matches;
331	      applyPauseState();
332	    });
333	
334	    // Keep multiple open tabs/windows of this page in sync with each other.
335	    window.addEventListener('storage', (e) => {
336	      if (e.key !== STORAGE_KEY || !e.newValue) return;
337	      try {
338	        const saved = JSON.parse(e.newValue);
339	        if (Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex] && saved.speedIndex !== speedIndex) {
340	          speedIndex = saved.speedIndex;
341	          circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
342	        }
343	        if (typeof saved.manuallyPaused === 'boolean') {
344	          manuallyPaused = saved.manuallyPaused;
345	          userHasChosen = true;
346	        }
347	        applyPauseState();
348	      } catch {
349	        // Ignore malformed storage updates from other tabs.
350	      }
351	    });
352	
353	    applyPauseState();
354	    updateLabels();
355	    document.body.classList.add('js-ready');
356	  </script>
357	</body>
358	</html>
